INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('fr-t2','official-fr-travel-public','dialogue','Bạn muốn đặt phòng khách sạn. Chọn câu phù hợp.','["Je voudrais faire une réservation.","Pouvez-vous répéter, s’il vous plaît ?","Où est la gare la plus proche ?","Veuillez confirmer la salle."]','["Je voudrais faire une réservation."]','[]','','','','','','','',0,1,'','',2,'["hotel","dialogue"]',1,'2026-09-11','2026-09-11');
