INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('fr-t4','official-fr-travel-public','multiple_select','Khi nhận phòng khách sạn, thông tin nào nên xác nhận?','["Tên đặt phòng","Số đêm","Loại phòng","Mật khẩu mạng xã hội cá nhân"]','["Tên đặt phòng","Số đêm","Loại phòng"]','[]','','','','','','','',0,1,'','',3,'["hotel","practical"]',3,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('fr-t5','official-fr-travel-public','ordering','Sắp xếp quy trình xử lý thất lạc hành lý.','["Xác định quầy hỗ trợ","Cung cấp thông tin chuyến bay","Mô tả hành lý","Nhận mã hồ sơ","Theo dõi cập nhật"]','["Xác định quầy hỗ trợ Cung cấp thông tin chuyến bay Mô tả hành lý Nhận mã hồ sơ Theo dõi cập nhật"]','[]','','','','','','','',0,1,'','',4,'["travel","workflow"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('fr-t6','official-fr-travel-public','reading_group','Đâu là thông tin quan trọng nhất trong bảng thông báo?','["Cổng mới và giờ boarding","Màu máy bay","Tên phi công","Giá vé năm sau"]','["Cổng mới và giờ boarding"]','[]','','','','','','','',0,1,'Gate changed from B12 to C04. Boarding begins at 18:20. Passengers should arrive at the gate at least 20 minutes before departure.','',3,'["travel","reading"]',5,'2026-09-11','2026-09-11');
