INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('fr-t8','official-fr-travel-public','roleplay','Role-play: nhân viên nói bạn chưa có tên trong danh sách đặt phòng. Cách phản hồi tốt nhất?','["Bình tĩnh đưa mã đặt chỗ và đề nghị họ kiểm tra lại.","Nổi giận và bỏ đi.","Đưa thông tin không liên quan.","Yêu cầu người khác tự giải quyết."]','["Bình tĩnh đưa mã đặt chỗ và đề nghị họ kiểm tra lại."]','[]','','','','','','','',0,1,'','',5,'["hotel","problem-solving"]',7,'2026-09-11','2026-09-11');

