INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s2','official-ru-school-scenario','scenario_decision','Bạn đến trường nhưng không tìm thấy phòng học mới. Nên làm gì trước?','["Kiểm tra thông báo và hỏi đầu mối phụ trách","Tự chọn một phòng bất kỳ","Về nhà ngay","Đợi mà không báo ai"]','["Kiểm tra thông báo và hỏi đầu mối phụ trách"]','[]','','','','','','','',0,1,'','',3,'["school-workplace","scenario"]',1,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s3','official-ru-school-scenario','multiple_select','Chọn thông tin nên có trong thông báo đổi phòng học.','["Phòng mới","Thời gian áp dụng","Đầu mối hỗ trợ","Tin đồn không liên quan"]','["Phòng mới","Thời gian áp dụng","Đầu mối hỗ trợ"]','[]','','','','','','','',0,1,'','',3,'["school","communication"]',2,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s4','official-ru-school-scenario','ordering','Sắp xếp quy trình chuẩn bị một buổi học.','["Xác nhận phòng","Chuẩn bị nội dung","Kiểm tra thiết bị","Đón học viên","Tổng kết"]','["Xác nhận phòng Chuẩn bị nội dung Kiểm tra thiết bị Đón học viên Tổng kết"]','[]','','','','','','','',0,1,'','',4,'["school","workflow"]',3,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s5','official-ru-school-scenario','error_correction','Chọn thông báo phù hợp nhất khi phải đổi lịch đột xuất.','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin.","Đổi giờ nha.","Tự xem lại đi.","Không cần thông báo."]','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin."]','[]','','','','','','','',0,1,'','',4,'["school","formal"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s6','official-ru-school-scenario','reading_group','Từ thông báo, hành động nào cần làm trước buổi học?','["Kiểm tra địa điểm mới và đến sớm","Chỉ đến sau giờ học","Không đọc thông báo","Tự đổi sang ngày khác"]','["Kiểm tra địa điểm mới và đến sớm"]','[]','','','','','','','',0,1,'Ban tổ chức thông báo phòng học thay đổi. Học viên cần kiểm tra địa điểm mới, có mặt trước 10 phút và liên hệ đầu mối nếu gặp khó khăn.','',3,'["reading","school"]',5,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s7','official-ru-school-scenario','translation','Diễn đạt/nhận diện câu dùng để xác nhận phòng học: “Пожалуйста, подтвердите номер аудитории.”','[]','["Пожалуйста, подтвердите номер аудитории.","Vui lòng xác nhận số phòng học."]','[]','','','','','','','',0,1,'','',3,'["translation","school"]',6,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s8','official-ru-school-scenario','roleplay','Role-play: bạn là người phụ trách lớp và có học viên đến nhầm phòng. Phản hồi nào tốt nhất?','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau.","Bạn tự tìm đi.","Không phải việc của mình.","Im lặng."]','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau."]','[]','','','','','','','',0,1,'','',5,'["roleplay","school-workplace"]',7,'2026-09-11','2026-09-11');

INSERT OR REPLACE INTO question_sets(id,title,language,level,topic,context,skill,description,is_official,visibility,status,version,created_by,created_at,updated_at) VALUES ('official-ru-travel-public','Русский — Travel & Public Services','ru','Everyday / Intermediate','Travel & Public Services','Travel','Dialogue / Reading / Scenario','Sân bay, khách sạn, phương tiện, hỏi đường và dịch vụ công cộng.',1,'public','published',1,NULL,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t1','official-ru-travel-public','dialogue','Bạn cần hỏi đường tới ga gần nhất. Chọn câu phù hợp.','["Где ближайшая станция?","Я хотел бы забронировать номер.","Пожалуйста, подтвердите номер аудитории.","Повторите, пожалуйста."]','["Где ближайшая станция?"]','[]','','','','','','','',0,1,'','',2,'["travel","dialogue"]',0,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t2','official-ru-travel-public','dialogue','Bạn muốn đặt phòng khách sạn. Chọn câu phù hợp.','["Я хотел бы забронировать номер.","Повторите, пожалуйста.","Где ближайшая станция?","Пожалуйста, подтвердите номер аудитории."]','["Я хотел бы забронировать номер."]','[]','','','','','','','',0,1,'','',2,'["hotel","dialogue"]',1,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t3','official-ru-travel-public','scenario_decision','Chuyến bay bị hoãn 45 phút và bạn có chuyến nối chuyến. Nên làm gì?','["Kiểm tra cổng/giờ mới và liên hệ hãng nếu nguy cơ lỡ nối chuyến","Rời sân bay không báo ai","Bỏ hành lý","Tắt điện thoại"]','["Kiểm tra cổng/giờ mới và liên hệ hãng nếu nguy cơ lỡ nối chuyến"]','[]','','','','','','','',0,1,'','',4,'["airport","scenario"]',2,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t4','official-ru-travel-public','multiple_select','Khi nhận phòng khách sạn, thông tin nào nên xác nhận?','["Tên đặt phòng","Số đêm","Loại phòng","Mật khẩu mạng xã hội cá nhân"]','["Tên đặt phòng","Số đêm","Loại phòng"]','[]','','','','','','','',0,1,'','',3,'["hotel","practical"]',3,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t5','official-ru-travel-public','ordering','Sắp xếp quy trình xử lý thất lạc hành lý.','["Xác định quầy hỗ trợ","Cung cấp thông tin chuyến bay","Mô tả hành lý","Nhận mã hồ sơ","Theo dõi cập nhật"]','["Xác định quầy hỗ trợ Cung cấp thông tin chuyến bay Mô tả hành lý Nhận mã hồ sơ Theo dõi cập nhật"]','[]','','','','','','','',0,1,'','',4,'["travel","workflow"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t6','official-ru-travel-public','reading_group','Đâu là thông tin quan trọng nhất trong bảng thông báo?','["Cổng mới và giờ boarding","Màu máy bay","Tên phi công","Giá vé năm sau"]','["Cổng mới và giờ boarding"]','[]','','','','','','','',0,1,'Gate changed from B12 to C04. Boarding begins at 18:20. Passengers should arrive at the gate at least 20 minutes before departure.','',3,'["travel","reading"]',5,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t7','official-ru-travel-public','true_false','Trong tình huống khẩn cấp ở nơi công cộng, nên cung cấp địa điểm và mô tả sự việc rõ ràng khi yêu cầu hỗ trợ.','["True","False"]','["True"]','[]','','','','','','','',0,1,'','',3,'["public-services","safety"]',6,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-t8','official-ru-travel-public','roleplay','Role-play: nhân viên nói bạn chưa có tên trong danh sách đặt phòng. Cách phản hồi tốt nhất?','["Bình tĩnh đưa mã đặt chỗ và đề nghị họ kiểm tra lại.","Nổi giận và bỏ đi.","Đưa thông tin không liên quan.","Yêu cầu người khác tự giải quyết."]','["Bình tĩnh đưa mã đặt chỗ và đề nghị họ kiểm tra lại."]','[]','','','','','','','',0,1,'','',5,'["hotel","problem-solving"]',7,'2026-09-11','2026-09-11');

