INSERT OR REPLACE INTO question_sets(id,title,language,level,topic,context,skill,description,is_official,visibility,status,version,created_by,created_at,updated_at) VALUES ('official-ar-school-scenario','العربية — School & Classroom Scenarios','ar','School / Intermediate','School & Classroom','School Workplace','Dialogue / Reading / Scenario','Bài tập thực tế ở trường: đổi lịch, đổi phòng, thông báo, phối hợp và xử lý tình huống lớp học.',1,'public','published',1,NULL,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s1','official-ar-school-scenario','dialogue','Bạn chưa nghe rõ hướng dẫn. Chọn cách yêu cầu nhắc lại lịch sự nhất.','["هل يمكنك التكرار من فضلك؟","Không cần nói gì.","Nói thật to một từ bất kỳ.","Rời cuộc trò chuyện."]','["هل يمكنك التكرار من فضلك؟"]','[]','','','','','','','',0,1,'','',2,'["school","dialogue","politeness"]',0,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s2','official-ar-school-scenario','scenario_decision','Bạn đến trường nhưng không tìm thấy phòng học mới. Nên làm gì trước?','["Kiểm tra thông báo và hỏi đầu mối phụ trách","Tự chọn một phòng bất kỳ","Về nhà ngay","Đợi mà không báo ai"]','["Kiểm tra thông báo và hỏi đầu mối phụ trách"]','[]','','','','','','','',0,1,'','',3,'["school-workplace","scenario"]',1,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s3','official-ar-school-scenario','multiple_select','Chọn thông tin nên có trong thông báo đổi phòng học.','["Phòng mới","Thời gian áp dụng","Đầu mối hỗ trợ","Tin đồn không liên quan"]','["Phòng mới","Thời gian áp dụng","Đầu mối hỗ trợ"]','[]','','','','','','','',0,1,'','',3,'["school","communication"]',2,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s4','official-ar-school-scenario','ordering','Sắp xếp quy trình chuẩn bị một buổi học.','["Xác nhận phòng","Chuẩn bị nội dung","Kiểm tra thiết bị","Đón học viên","Tổng kết"]','["Xác nhận phòng Chuẩn bị nội dung Kiểm tra thiết bị Đón học viên Tổng kết"]','[]','','','','','','','',0,1,'','',4,'["school","workflow"]',3,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s5','official-ar-school-scenario','error_correction','Chọn thông báo phù hợp nhất khi phải đổi lịch đột xuất.','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin.","Đổi giờ nha.","Tự xem lại đi.","Không cần thông báo."]','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin."]','[]','','','','','','','',0,1,'','',4,'["school","formal"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s6','official-ar-school-scenario','reading_group','Từ thông báo, hành động nào cần làm trước buổi học?','["Kiểm tra địa điểm mới và đến sớm","Chỉ đến sau giờ học","Không đọc thông báo","Tự đổi sang ngày khác"]','["Kiểm tra địa điểm mới và đến sớm"]','[]','','','','','','','',0,1,'Ban tổ chức thông báo phòng học thay đổi. Học viên cần kiểm tra địa điểm mới, có mặt trước 10 phút và liên hệ đầu mối nếu gặp khó khăn.','',3,'["reading","school"]',5,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s7','official-ar-school-scenario','translation','Diễn đạt/nhận diện câu dùng để xác nhận phòng học: “يرجى تأكيد رقم القاعة.”','[]','["يرجى تأكيد رقم القاعة.","Vui lòng xác nhận số phòng học."]','[]','','','','','','','',0,1,'','',3,'["translation","school"]',6,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ar-s8','official-ar-school-scenario','roleplay','Role-play: bạn là người phụ trách lớp và có học viên đến nhầm phòng. Phản hồi nào tốt nhất?','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau.","Bạn tự tìm đi.","Không phải việc của mình.","Im lặng."]','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau."]','[]','','','','','','','',0,1,'','',5,'["roleplay","school-workplace"]',7,'2026-09-11','2026-09-11');

